"use strict";

/*
 * Converts RME items.otb/XML data to TibiaGo's definitions.json format.
 *
 * TibiaGo 7.40 was originally generated by tools/rewrite-items-xml.js. This
 * converter deliberately preserves that format and its server behaviour,
 * then layers version-specific RME data on top for newer clients.
 *
 * Examples:
 *   node scripts/convert-rme-items.js --version 740 --source C:\RME\data\740
 *   node scripts/convert-rme-items.js --version 760 --source C:\RME\data\760
 *
 * Server definitions are keyed by server ID. When the default output is used,
 * a separate client definitions file is also generated and keyed by client ID.
 */

const fs = require("fs");
const path = require("path");
const { parseStringPromise } = require("xml2js");
const otb2json = require("../tools/lib/otb2json");

const ROOT = path.resolve(__dirname, "..");
const NUMERIC_CHILD_PROPERTIES = new Set([
  "absorbPercentFire", "absorbPercentPhysical", "absorbPercentEnergy",
  "absorbPercentPoison", "absorbPercentLifeDrain", "transformDeEquipTo",
  "transformEquipTo", "writeOnceItemId", "maxTextLen", "decayTo",
  "healthGain", "healthTicks", "manaGain", "manaTicks", "duration",
  "weight", "defense", "charges", "containerSize", "armor", "attack",
  "speed"
]);
const BOOLEAN_CHILD_PROPERTIES = new Set([
  "showduration", "allowpickupable", "blockprojectile", "writeable",
  "readable", "stopduration", "manashield", "showcharges",
  "suppressDrunk", "preventitemloss", "magicpoints", "invisible"
]);
const DIRECT_ALIASES = {
  arm: "armor",
  blockingprojectile: "blockProjectile",
  decaytime: "duration",
  decayto: "decayTo",
  defence: "defense",
  descr: "description",
  maglevel: "magicLevel",
  maxitems: "containerSize",
  position: "slotType",
  skill: "weaponType"
};
const NUMERIC_DIRECT_PROPERTIES = new Set([
  "armor", "attack", "charges", "containerSize", "damage", "decayTo",
  "defense", "duration", "magicLevel", "weight"
]);
const VERTICAL_ITEMS = new Set([2037, 2038, 1818, 2060, 2061, 2066, 2067]);
const HORIZONTAL_ITEMS = new Set([2039, 2040, 1811, 2058, 2059, 2068, 2069]);
const EXPERTISE_ITEMS = new Set([1227, 1228, 1229, 1230, 1245, 1246, 1247, 1248, 1259, 1260, 1261, 1262]);
const UNWANTED_ITEMS = new Set([1223, 1224, 1225, 1226]);

function option(name) {
  const index = process.argv.indexOf(name);
  return index === -1 ? null : process.argv[index + 1];
}

async function readItemsXml(filename) {
  if (!filename || !fs.existsSync(filename)) return [];
  const document = await parseStringPromise(fs.readFileSync(filename, "utf8"));
  return document.items && document.items.item ? document.items.item : [];
}

function itemRange(item) {
  const attributes = item.$ || {};
  const first = Number(attributes.fromid || attributes.id);
  const last = Number(attributes.toid || attributes.id);
  if (!Number.isInteger(first) || !Number.isInteger(last)) return [];
  const result = [];
  for (let id = first; id <= last; id++) result.push(id);
  return result;
}

function childValue(key, value) {
  if (NUMERIC_CHILD_PROPERTIES.has(key)) return Number(value);
  // Keep the original 7.40 converter semantics so validation is exact.
  if (BOOLEAN_CHILD_PROPERTIES.has(key)) return Boolean(value);
  return value;
}

function applyClassicXml(items, entries, merge) {
  let applied = 0;
  for (const item of items) {
    const itemAttributes = item.$ || {};
    for (const id of itemRange(item)) {
      const entry = entries[id];
      if (!entry) continue;
      const properties = merge && entry.properties !== null ? entry.properties : {
        article: itemAttributes.article,
        name: itemAttributes.name
      };

      if (merge) {
        if (itemAttributes.article !== undefined) properties.article = itemAttributes.article;
        if (itemAttributes.name !== undefined) properties.name = itemAttributes.name;
        if (itemAttributes.charges !== undefined) properties.charges = Number(itemAttributes.charges);
        if (itemAttributes.time !== undefined) properties.duration = Number(itemAttributes.time);
        if (itemAttributes.questbox !== undefined) properties.questbox = Number(itemAttributes.questbox);
      }

      for (const child of item.attribute || []) {
        const attribute = child.$ || {};
        if (!attribute.key) continue;
        properties[attribute.key] = childValue(attribute.key, attribute.value);
      }

      entry.properties = properties;
      applied++;
    }
  }
  return applied;
}

function directValue(key, value) {
  if (value === undefined || value === "") return undefined;
  if (key === "weight") return Math.round(Number(value) * 100);
  if (NUMERIC_DIRECT_PROPERTIES.has(key)) return Number(value);
  return value;
}

function applyRmeSupplement(items, entries) {
  let applied = 0;
  for (const item of items) {
    const attributes = item.$ || {};
    for (const id of itemRange(item)) {
      const entry = entries[id];
      // The complete 7.40 XML remains authoritative for existing items.
      if (!entry || entry.properties !== null) continue;
      const properties = {};
      for (const [rawKey, rawValue] of Object.entries(attributes)) {
        if (["id", "fromid", "toid", "editorsuffix"].includes(rawKey)) continue;
        const key = DIRECT_ALIASES[rawKey] || rawKey;
        const value = directValue(key, rawValue);
        if (value !== undefined && !Number.isNaN(value)) properties[key] = value;
      }
      entry.properties = properties;
      applied++;
    }
  }
  return applied;
}

function finishEntry(serverId, entry) {
  const properties = entry.properties || {};
  const originalFlags = entry.flags;

  if (entry.group === 0x02 && properties.type === undefined) properties.type = "container";
  if (entry.group === 0x06) {
    properties.type = "rune";
    properties.stackable = true;
  }
  if (entry.group === 0x0B) properties.type = "splash";
  if (entry.group === 0x0C) properties.type = "fluidContainer";
  if (properties.corpseType !== undefined && properties.containerSize !== undefined) properties.type = "corpse";

  if (EXPERTISE_ITEMS.has(serverId)) properties.expertise = true;
  if (UNWANTED_ITEMS.has(serverId)) properties.unwanted = true;
  if (VERTICAL_ITEMS.has(serverId)) entry.flags += 131072;
  if (HORIZONTAL_ITEMS.has(serverId)) entry.flags += 262144;
  if (serverId === 2593) properties.type = "mailbox";
  if (serverId === 2598) {
    delete properties.readable;
    properties.type = "readable";
  }
  if (serverId === 1811 || serverId === 1818) entry.flags += 1048576;
  if ((originalFlags & (1 << 14)) || (originalFlags & (1 << 20))) properties.type = "readable";
  if (entry.node.speed) properties.friction = entry.node.speed;

  entry.properties = properties;
  delete entry.node;
}

function indexByClientId(entries) {
  const clientEntries = {};

  for (const entry of Object.values(entries)) {
    // Fluid pseudo-items use client ID 0 and are never rendered directly.
    if (!Number.isInteger(entry.id) || entry.id <= 0) continue;
    if (clientEntries[entry.id]) {
      throw new Error(`Duplicate client item ID ${entry.id}`);
    }
    clientEntries[entry.id] = entry;
  }

  return clientEntries;
}

async function main() {
  const version = option("--version");
  const sourceArgument = option("--source");
  const outputArgument = option("--output");
  const clientOutputArgument = option("--client-output");
  const baseArgument = option("--base");
  if (!version || !sourceArgument) {
    throw new Error("Usage: node scripts/convert-rme-items.js --version <version> --source <RME version directory> [--base <complete items.xml>] [--output <server-definitions.json>] [--client-output <client-definitions.json>]");
  }

  const source = path.resolve(sourceArgument);
  const output = path.resolve(outputArgument || path.join(ROOT, "data", version, "items", "definitions.json"));
  const clientOutput = clientOutputArgument
    ? path.resolve(clientOutputArgument)
    : outputArgument
      ? null
      : path.join(ROOT, "client", "data", version, "definitions.json");
  const otbFile = path.join(source, "items.otb");
  const versionXml = path.join(source, "items.xml");
  const supplementXml = path.join(source, "items2.xml");
  const inferredBase = version === "740" ? versionXml : path.join(source, "..", "740", "items.xml");
  const baseXml = path.resolve(baseArgument || inferredBase);

  if (!fs.existsSync(otbFile)) throw new Error(`Missing ${otbFile}`);
  if (!fs.existsSync(baseXml)) throw new Error(`Missing complete base XML ${baseXml}`);

  const entries = {};
  const otb = otb2json.read(otbFile);
  for (const node of otb.children || []) {
    if (!Number.isInteger(node.sid) || !Number.isInteger(node.cid)) continue;
    entries[node.sid] = {
      id: node.cid,
      flags: node.flags,
      group: node.group,
      node,
      properties: null
    };
  }

  const baseItems = await readItemsXml(baseXml);
  const supplementItems = await readItemsXml(supplementXml);
  const versionItems = path.resolve(versionXml) === path.resolve(baseXml) ? [] : await readItemsXml(versionXml);
  const baseApplied = applyClassicXml(baseItems, entries, false);
  const supplementApplied = applyRmeSupplement(supplementItems, entries);
  const versionApplied = applyClassicXml(versionItems, entries, true);

  for (const [serverId, entry] of Object.entries(entries)) finishEntry(Number(serverId), entry);

  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, JSON.stringify(entries, null, 4));

  const values = Object.values(entries);
  let clientCount = 0;
  if (clientOutput) {
    const clientEntries = indexByClientId(entries);
    fs.mkdirSync(path.dirname(clientOutput), { recursive: true });
    fs.writeFileSync(clientOutput, JSON.stringify(clientEntries, null, 4));
    clientCount = Object.keys(clientEntries).length;
  }

  const named = values.filter(entry => entry.properties.name).length;
  const friction = values.filter(entry => entry.properties.friction !== undefined).length;
  console.log(`Converted ${values.length} OTB entries for ${version}.`);
  console.log(`Applied base=${baseApplied}, supplement=${supplementApplied}, version overrides=${versionApplied}.`);
  console.log(`Named=${named}, friction=${friction}, output=${output}`);
  if (clientOutput) console.log(`Client-indexed=${clientCount}, output=${clientOutput}`);
}

main().catch(error => {
  console.error(error.stack || error.message);
  process.exitCode = 1;
});
